sources.DeliverySink.ts:
export interface DeliverySink {
  rejected(reason: string): void
}

sources.Direct.ts:
import { DeliverySink } from './DeliverySink'
export class Direct {
  forward(target: DeliverySink): void {
    target.rejected('bad payload')
  }
}

sources.OtherReceiver.ts:
import { DeliverySink } from './DeliverySink'
export class OtherReceiver {
  forward(target: DeliverySink): void {
    fallback.rejected(target)
  }
}

sources.CommentOnly.ts:
import { DeliverySink } from './DeliverySink'
export class CommentOnly {
  forward(target: DeliverySink): void {
    // target.rejected('documentation only')
    record(target)
  }
}

sources.DifferentParameter.ts:
import { DeliverySink } from './DeliverySink'
export class DifferentParameter {
  forward(target: DeliverySink, other: OtherSink): void {
    record(target)
    other.rejected('bad payload')
  }
}
